//! Raw bindings to the C library of the Sylvac BLE SDK (`sylvac_ble.dll`, `libsylvac_ble.so`),
//! as declared in `sylvac_ble.h`. Most programs use the safe crate `sylvac-ble` instead.
//!
//! The library is not built from source: the build script links the prebuilt one found in the
//! folder named by the environment variable `SYLVAC_BLE_SDK_DIR` (see the README).
//!
//! `bindings.rs` is generated by bindgen from the header and checked against it by the SDK's own
//! tests; the functions' documentation is the header's.
#![no_std]
#![allow(non_camel_case_types)]
// The generated documentation is C documentation.
#![allow(clippy::doc_lazy_continuation, clippy::missing_safety_doc)]

include!("bindings.rs");

#[cfg(test)]
mod tests {
    use core::mem::{align_of, offset_of, size_of};

    use super::*;

    /// The sizes and offsets of `sylvac_ble.h` on this target, by the formulas of the SDK's
    /// documentation: `P` is the pointer size; `double` and `uint64_t` are 8-aligned on every
    /// supported target (not on 32-bit x86 Linux, which is not one).
    #[test]
    fn layout_is_the_documented_one() {
        const P: usize = size_of::<usize>();
        let up = |n: usize, a: usize| n.div_ceil(a) * a;
        assert_eq!(size_of::<sylvac_ble_mac>(), 6);
        assert_eq!(align_of::<sylvac_ble_mac>(), 1);
        assert_eq!(size_of::<sylvac_ble_config>(), up(32 + P, P));
        assert_eq!(offset_of!(sylvac_ble_config, ports), 32);
        assert_eq!(size_of::<sylvac_ble_central>(), up(4 * P + 28, P));
        assert_eq!(offset_of!(sylvac_ble_central, mac), 4 * P);
        assert_eq!(offset_of!(sylvac_ble_central, kind), 4 * P + 8);
        assert_eq!(offset_of!(sylvac_ble_central, is_full), 4 * P + 24);
        assert_eq!(size_of::<sylvac_ble_advertiser>(), up(3 * P + 56, 8));
        assert_eq!(offset_of!(sylvac_ble_advertiser, date_received_ms), 8);
        assert_eq!(offset_of!(sylvac_ble_advertiser, rssi), 3 * P + 24);
        assert_eq!(
            offset_of!(sylvac_ble_advertiser, is_low_battery),
            3 * P + 52
        );
        assert_eq!(size_of::<sylvac_ble_numerical_value_changed_event>(), 32);
        assert_eq!(
            offset_of!(sylvac_ble_numerical_value_changed_event, peripheral),
            8
        );
        assert_eq!(
            offset_of!(sylvac_ble_numerical_value_changed_event, measurement_params),
            16
        );
        assert_eq!(size_of::<sylvac_ble_measuring_params>(), 16);
        assert_eq!(size_of::<sylvac_ble_measurement_params_changed_event>(), 24);
        assert_eq!(size_of::<sylvac_ble_central_to_connect_changed_event>(), 28);
        assert_eq!(align_of::<sylvac_ble_event_data>(), 8);
        assert_eq!(size_of::<sylvac_ble_event_data>(), up(3 * P + 56, 8));
        assert_eq!(offset_of!(sylvac_ble_event, data), 8);
        assert_eq!(size_of::<sylvac_ble_event>(), 8 + up(3 * P + 56, 8));
        assert_eq!(size_of::<sylvac_ble_peripheral_state>(), 64);
        assert_eq!(
            offset_of!(sylvac_ble_peripheral_state, measurement_params),
            48
        );
        assert_eq!(size_of::<sylvac_ble_central_list>(), 8 + P);
        assert_eq!(offset_of!(sylvac_ble_central_list, items), 8);
        assert_eq!(size_of::<sylvac_ble_advertiser_list>(), 8 + P);
        assert_eq!(size_of::<sylvac_ble_peripheral_list>(), 8 + P);
    }

    /// Links and calls the library: the version functions and the configuration defaults.
    #[test]
    fn the_library_answers() {
        // SAFETY: the version calls take no argument and return static NUL-terminated texts;
        // `config` is a valid struct to fill.
        unsafe {
            assert_eq!(sylvac_ble_abi_version() >> 16, SYLVAC_BLE_ABI_VERSION >> 16);
            let version = core::ffi::CStr::from_ptr(sylvac_ble_version());
            assert!(!version.to_bytes().is_empty());
            let mut config = core::mem::zeroed::<sylvac_ble_config>();
            assert_eq!(sylvac_ble_config_init(&mut config), SYLVAC_BLE_OK);
            assert_eq!(config.struct_size as usize, size_of::<sylvac_ble_config>());
            assert_eq!(config.hot_plug, 1);
            assert_eq!(config.queue_capacity, 10_000);
            assert_eq!(
                sylvac_ble_config_init(core::ptr::null_mut()),
                SYLVAC_BLE_ERR_INVALID_ARGUMENT
            );
        }
    }
}
